def order(api, customer_id="c1", *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_empty_for_customer_without_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_newest_first_with_totals_matching_summary(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("LAMP", 2)).body["order_id"]

    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert [o["order_id"] for o in body["orders"]] == [second, first]
    for entry in body["orders"]:
        summary = shop.orders.handle_get(entry["order_id"]).body
        assert entry["total_cents"] == summary["total_cents"]
        assert entry["status"] == summary["status"]
    # LAMP x2 for a standard customer carries a discount: 12000 - 1200.
    assert body["orders"][0] == {"order_id": second, "status": "placed", "total_cents": 10800}


def test_order_history_includes_cancelled_orders_with_status(shop):
    oid = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    body = shop.insights.handle_order_history("c1").body
    assert body["orders"] == [{"order_id": oid, "status": "cancelled", "total_cents": 2500}]


def test_order_history_gold_discount_in_total(shop):
    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c2").body
    assert body["orders"] == [{"order_id": oid, "status": "placed", "total_cents": 10200}]


def test_insights_is_exposed_on_api(api):
    from orders.controllers.customer_insights import CustomerInsightsController
    assert isinstance(api.insights, CustomerInsightsController)

