"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        body: dict[str, Any] = {
            "customer_id": customer_id,
            "orders": [{"order_id": s.order.order_id, "status": s.order.status,
                        "total_cents": s.total_cents} for s in summaries],
        }
        return Response(200, body)

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            order_count, lifetime_value_cents = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value_cents})

def order(api, customer_id="c1", *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_empty_for_customer_without_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_newest_first_with_totals_matching_summary(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("LAMP", 2)).body["order_id"]

    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert [o["order_id"] for o in body["orders"]] == [second, first]
    for entry in body["orders"]:
        summary = shop.orders.handle_get(entry["order_id"]).body
        assert entry["total_cents"] == summary["total_cents"]
        assert entry["status"] == summary["status"]
    # LAMP x2 for a standard customer carries a discount: 12000 - 1200.
    assert body["orders"][0] == {"order_id": second, "status": "placed", "total_cents": 10800}


def test_order_history_includes_cancelled_orders_with_status(shop):
    oid = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    body = shop.insights.handle_order_history("c1").body
    assert body["orders"] == [{"order_id": oid, "status": "cancelled", "total_cents": 2500}]


def test_order_history_gold_discount_in_total(shop):
    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c2").body
    assert body["orders"] == [{"order_id": oid, "status": "placed", "total_cents": 10200}]


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_zero_for_customer_without_orders(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_sums_non_cancelled_orders_with_discounts(shop):
    order(shop, "c1", ("BOOK", 1))                    # 2500, no discount
    lamp = order(shop, "c1", ("LAMP", 2)).body["order_id"]  # 12000 - 1200 = 10800
    cancelled = order(shop, "c1", ("PEN", 10)).body["order_id"]  # 3000, cancelled
    shop.orders.handle_cancel(cancelled)
    order(shop, "c2", ("PEN", 1))                     # other customer, ignored

    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2,
                             "lifetime_value_cents": 2500 + 10800}
    # Consistent with the order history totals.
    history = shop.insights.handle_order_history("c1").body["orders"]
    assert sum(o["total_cents"] for o in history if o["status"] != "cancelled") == 13300
    assert lamp in [o["order_id"] for o in history]


def test_lifetime_value_all_cancelled_is_zero(shop):
    oid = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    response = shop.insights.handle_lifetime_value("c1")
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_insights_is_exposed_on_api(api):
    from orders.controllers.customer_insights import CustomerInsightsController
    assert isinstance(api.insights, CustomerInsightsController)

